import re
s=open('getters.go').read()
old=re.compile(r'\tsec, ok := c\.sections\[section\]\n\tif !ok \{\n\t\treturn (\S+), fmt\.Errorf\("kvconf: no section %q", section\)\n\t\}\n\tv, ok := sec\[key\]\n\tif !ok \{\n\t\treturn \S+, fmt\.Errorf\([^\n]*\)\n\t\}\n')
def rep(m):
    z=m.group(1)
    return f'\tv, err := c.lookup(section, key)\n\tif err != nil {{\n\t\treturn {z}, err\n\t}}\n'
s=old.sub(rep,s)
# GetBool: keep its own missing-key wording
s=s.replace('''	v, err := c.lookup(section, key)
	if err != nil {
		return false, err
	}
	switch''','''	v, err := c.lookup(section, key)
	if err != nil {
		var mk *missingKeyError
		if errors.As(err, &mk) {
			return false, fmt.Errorf("kvconf: %s: key %q not set", sectionLabel(section), key)
		}
		return false, err
	}
	switch''')
s=s.replace('import (\n','import (\n\t"errors"\n')
s=s.replace('''// Get returns''','''// missingKeyError reports that a section exists but does not contain a key.
type missingKeyError struct {
	section, key string
}

func (e *missingKeyError) Error() string {
	return fmt.Sprintf("kvconf: %s: no key %q", sectionLabel(e.section), e.key)
}

// lookup returns the raw value of key in section.
func (c *Config) lookup(section, key string) (string, error) {
	sec, ok := c.sections[section]
	if !ok {
		return "", fmt.Errorf("kvconf: no section %q", section)
	}
	v, ok := sec[key]
	if !ok {
		return "", &missingKeyError{section, key}
	}
	return v, nil
}

// Get returns''',1)
open('getters.go','w').write(s)
