func TestGetterErrorMessages(t *testing.T) {
	c, err := Parse(strings.NewReader("top=1\n[a]\nx=1\n"))
	if err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name string
		err  func() error
		want string
	}{
		{"Get section", func() error { _, e := c.Get("zz", "x"); return e }, `kvconf: no section "zz"`},
		{"Get key", func() error { _, e := c.Get("a", "y"); return e }, `kvconf: [a]: no key "y"`},
		{"Get top key", func() error { _, e := c.Get("", "y"); return e }, `kvconf: top level: no key "y"`},
		{"GetInt section", func() error { _, e := c.GetInt("zz", "x"); return e }, `kvconf: no section "zz"`},
		{"GetInt key", func() error { _, e := c.GetInt("a", "y"); return e }, `kvconf: [a]: no key "y"`},
		{"GetBool section", func() error { _, e := c.GetBool("zz", "x"); return e }, `kvconf: no section "zz"`},
		{"GetBool key", func() error { _, e := c.GetBool("a", "y"); return e }, `kvconf: [a]: key "y" not set`},
		{"GetBool top key", func() error { _, e := c.GetBool("", "y"); return e }, `kvconf: top level: key "y" not set`},
		{"GetDuration section", func() error { _, e := c.GetDuration("zz", "x"); return e }, `kvconf: no section "zz"`},
		{"GetDuration key", func() error { _, e := c.GetDuration("a", "y"); return e }, `kvconf: [a]: no key "y"`},
	}
	for _, tc := range cases {
		if got := tc.err(); got == nil || got.Error() != tc.want {
			t.Errorf("%s: got %v, want %q", tc.name, got, tc.want)
		}
	}
}
